  $('overviewView').innerHTML=head('A clearer picture','Your day, in balance','Finances, work and progress. One personal space.',dateTools())+
   `<section class="summary-grid">${metric('All-time balance',eur(balance),`${eur(expenses)} spent in ${month}`)}${metric('Logged intake',loaded&&t.count?num(t.calories)+' kcal':'No data',t.count?`${t.count} entries · ${dailyLabel()} day${t.calories_unknown?' · known subtotal':''}`:'No entries is not zero intake')}${metric('Logged protein',t.count?num(t.protein_g)+' g':'No data',C.numeric(g.protein_g)?`Approximate goal ${num(g.protein_g)} g · ${t.protein_g_unknown||0} unknown values`:'Set an optional goal in Settings')}${metric('Latest measurement',recent?num(recent.weight_kg)+' kg':'No dated weigh-ins',recent?recent.logged_on:'Undated references stay out of charts')}</section>
   <section class="dashboard-grid"><article class="card"><div class="section-title"><div><h2>Seven days of nutrition</h2><p class="metric-note">Logged calories · gaps mean no data</p></div>${button('goto-nutrition','Open diary')}</div>${nutritionChart(points,'calories')}<div class="legend"><span>Label / user supplied</span><span class="estimate">Estimated / unverified</span></div></article>
   <article class="card"><div class="eyebrow">This month · ${E(month)}</div><h2>Work & money</h2><div class="metric">${num(hours)} <span class="muted">hours</span></div><p class="metric-note">${eur(shifts.reduce((a,s)=>a+s.hours*s.hourlyRate,0))} gross wages · ${eur(income)} recorded income</p><hr class="chart-grid"><h3>Savings progress</h3>${finance.goal?`<p class="metric-note">${E(finance.goal.name)} · ${eur(Math.max(0,balance))} / ${eur(finance.goal.amount)}</p>${progress(Math.max(0,balance),finance.goal.amount)}`:empty('Set a savings goal in Finances.')}</article></section>
   <section class="card section"><div class="section-title"><div><h2>Today’s focus</h2><p class="metric-note">Small actions, a useful record.</p></div></div><div class="toolbar">${button('new-entry','+ Log a meal')}${button('goto-weight','+ Record weight')}${button('goto-work','Log a shift')}${button('goto-finance','Add transaction')}</div>${g.protein_g&&C.numeric(t.protein_g)?progress(t.protein_g,g.protein_g):''}<p class="foot">Logging status: ${E(dailyLabel())}. Historical partial days are not nutritional targets. Maintenance and walking goals are estimates or intentions, not measured expenditure.</p></section>`;
