 function entryCard(r){return `<div class="list-item"><div class="list-main"><strong>${E(r.name)}</strong><p>${E(r.meal)}${r.logged_time?' · '+E(r.logged_time.slice(0,5)):''}${r.quantity?' · '+E(r.quantity)+' '+E(r.unit||''):''}</p><p>${num(r.calories)} kcal · ${num(r.protein_g)} g protein</p>${badge(C.estimate(r)?'Estimate / unverified':'Label / user supplied',C.estimate(r)?'uncertain':'')}${r.calories_low!==null&&r.calories_low!==undefined?` <span class="metric-note">${num(r.calories_low)}–${num(r.calories_high)} kcal</span>`:''}<details><summary>Source & notes</summary><p>${E(r.source)} · ${E(r.confidence)}</p><p>${E(r.notes)}</p>${r.evidence?`<p>${E(JSON.stringify(r.evidence))}</p>`:''}</details></div><div class="item-actions">${button('edit-entry','Edit',`data-id="${E(r.id)}"`)}${button('repeat-entry','Repeat',`data-id="${E(r.id)}"`)}${button('delete-entry','Delete',`data-id="${E(r.id)}"`)}</div></div>`;}
