  const dates=points.map(p=>Date.parse(p.logged_on)),minD=Math.min(...dates),span=Math.max(86400000,Math.max(...dates)-minD),min=Math.min(...points.map(p=>Number(p.weight_kg)))-1,max=Math.max(...points.map(p=>Number(p.weight_kg)))+1;
